"""Rust game type (native Linux dedicated server).

Everything is set on the launch line as "+server.<setting> value". Each server
has its own identity folder (world + player data) under the install. Rust has
no join password. Player numbers come from the Steam query port.
"""
from __future__ import annotations

import os

import config
import monitor
from games.base import ActionError, GameType, safe_name

EXE = "RustDedicated"

_RUN_TEMPLATE = """#!/bin/sh
# gamedash-managed Rust server — generated by provision().
# World and player data: {install}/server/{identity}
. {secrets}
cd "{install}" || exit 1
export LD_LIBRARY_PATH="$LD_LIBRARY_PATH:{install}/RustDedicated_Data/Plugins/x86_64"
exec ./{exe} -batchmode -nographics -logfile "{log}" \\
    +server.identity "{identity}" \\
    +server.port {gp} +server.queryport {qp} \\
    +rcon.ip 127.0.0.1 +rcon.port {rp} +rcon.password "$GAME_ADMIN_PASSWORD" +rcon.web 1 \\
    +app.port {ap} \\
    +server.hostname "{name}" +server.description "{description}" \\
    +server.maxplayers {maxp} +server.level "Procedural Map" \\
    +server.worldsize {size} +server.seed {seed} +server.saveinterval 300
"""


class RustGame(GameType):
    kind = "rust"
    label = "Rust"
    steam_app = 258550
    install_marker = EXE
    install_gb = 7
    ram_note = "about 8-12 GB of memory; more for big maps and many players"
    about = "Open-world survival and raiding. Heavy: slow first start and lots of memory."
    actions: set[str] = set()

    provisionable = True
    port_layout = [
        {"name": "game", "klass": "game", "start": 28015, "proto": "UDP", "forward": True,
         "label": "Game port (UDP)", "help": "The port players connect to. Forward it."},
        {"name": "query", "klass": "query", "start": 28017, "proto": "UDP", "forward": True,
         "label": "Steam query port (UDP)", "help": "Lists the server in the browser. Forward it."},
        {"name": "rcon", "klass": "rcon", "start": 28016, "proto": "TCP", "label": "Admin console port (TCP)",
         "form": False},
        {"name": "app", "klass": "query", "start": 28082, "proto": "TCP", "forward": True,
         "label": "Rust+ companion app port (TCP)",
         "help": "Only needed if players use the Rust+ phone app with this server."},
    ]
    extra_fields = [
        {"name": "maxplayers", "label": "Max players (1-500)", "type": "number", "min": 1, "max": 500,
         "default": 20},
        {"name": "worldsize", "label": "Map size (1000-6000; 3000 suits a small group)", "type": "number",
         "min": 1000, "max": 6000, "step": 500, "default": 3000,
         "help": "Bigger maps take longer to create and use more memory."},
        {"name": "seed", "label": "Map seed — a number; blank = random", "type": "number",
         "min": 1, "max": 2147483647, "placeholder": "random"},
        {"name": "description", "label": "Description shown in the server browser — optional",
         "placeholder": ""},
    ]
    provision_hint = ("Rust — a new map with its own save folder. Rust servers have no join password: "
                      "anyone who finds the server can join. The first start creates the map and can "
                      "take 5-10 minutes before the server appears.")

    def provision(self, spec: dict, ports: dict) -> dict:
        install = config.install_dir(self.kind)
        if not os.path.isfile(os.path.join(install, EXE)):
            raise ActionError(f"Rust isn't installed ({install}).")
        key = spec["key"]
        identity = "gd_" + key.replace("-", "_")
        ident_dir = os.path.join(install, "server", identity)
        if os.path.isdir(ident_dir):
            raise ActionError(f"A Rust save folder for this key already exists ({ident_dir}).")
        display = safe_name((spec.get("name") or key).strip()) or key
        seed = self.option(spec, "seed")
        if seed is None:
            seed = int.from_bytes(os.urandom(4), "big") % 2147483646 + 1
        os.makedirs(ident_dir, exist_ok=True)
        log = os.path.join(ident_dir, "server.log")
        run = os.path.join(install, f"gamedash-{key}-run.sh")
        with open(run, "w", encoding="utf-8") as f:
            f.write(_RUN_TEMPLATE.format(
                secrets=config.secrets_path(), install=install, exe=EXE, log=log, identity=identity,
                gp=ports["game"], qp=ports["query"], rp=ports["rcon"], ap=ports["app"],
                name=display, description=safe_name(spec.get("description") or "", 200),
                maxp=self.option(spec, "maxplayers"),
                size=self.option(spec, "worldsize"), seed=seed))
        os.chmod(run, 0o755)
        return {
            "exec_start": run, "working_dir": install,
            "game_port": ports["game"], "query_port": ports["query"], "rcon_port": None,
            "a2s": True, "proc_match": f'+server.identity {identity}',
            "server_name": display, "join_port": ports["game"], "log_path": log,
            "install_dir": install, "steam_app": self.steam_app,
            # the stop signal makes the server save and quit
            "kill_signal": "SIGINT", "timeout_stop": 90,
            "world": identity, "save_root": ident_dir,
            "extra_ports": [ports["rcon"], ports["app"]],
        }

    def probe(self, s) -> dict:
        out = {"players": None, "player_names": [], "player_detail": [],
               "max_players": None, "reachable": None}
        info = monitor.a2s_info(s.query_port) if s.query_port else None
        if info is not None:
            names = monitor.a2s_player_names(s.query_port) if info["players"] else []
            out.update(reachable=True, players=info["players"], max_players=info["max_players"],
                       player_names=names, player_detail=[{"name": n, "id": ""} for n in names])
        return out
